.notes-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin-bottom:19px}.notes-stat{padding:20px!important}.notes-stat span{display:block;color:#7d8797;font-size:11px;font-weight:650}.notes-stat strong{display:block;color:#17284f;font-size:26px;margin:4px 0}.notes-stat small{font-size:10px;color:#929eae}.notes-filter{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:19px}.notes-filter input[type=search]{flex:1 1 260px}.notes-filter input[type=search],.notes-filter select{min-height:40px;padding:9px 11px;border:1px solid #d9e2ec;border-radius:8px;background:#fff;font-size:12px;color:#23334f}.notes-filter-check{display:inline-flex;align-items:center;gap:7px;font-size:12px;color:#5a6a80}.notes-filter-check input{accent-color:#168a82}.notes-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.notes-item{display:flex;flex-direction:column;gap:10px;padding:18px;border:1px solid #e5eaf1;border-radius:12px;background:#fff;min-height:175px;min-width:0;transition:border-color .15s,box-shadow .15s}.notes-item:hover{border-color:#b4ded2;box-shadow:0 8px 22px #17284f0c}.notes-item-head{display:flex;align-items:center;justify-content:space-between}.notes-icon{display:grid;place-items:center;background:#eaf7f3;color:#16836a;width:38px;height:38px;border-radius:10px;font-size:18px}.notes-badges{display:flex;gap:5px}.notes-badge{display:inline-block;border-radius:6px;padding:5px 9px;background:#f1f3f8;color:#65748b;font-size:10px;font-weight:750}.notes-badge.pinned{background:#e8f5ef;color:#16826b}.notes-item-title{display:block;font-weight:750;font-size:13px;color:#17284f;text-decoration:none;overflow-wrap:anywhere}.notes-item-title:hover{text-decoration:underline}.notes-item p{font-size:11px;color:#738197;line-height:1.65;margin:0;overflow-wrap:anywhere;flex:1}.notes-item-foot{display:flex;justify-content:space-between;gap:10px;align-items:center;border-top:1px solid #eef1f5;padding-top:12px}.notes-item-foot sma